package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"     // PIC X len=1 = "N"
var WsFirstFlag string = "Y"   // PIC X len=1 = "Y"
var WsPrevBranch string = "  " // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    " // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal      // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0 // PIC 99 len=2 = 0
var WsAmtEd string      // PIC ZZ,ZZ9.99 len=9
var WsBalEd string      // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string      // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var FileRec LedgerRec

var ledgerLines []string
var ledgerIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func FirstRecord() bool {
	return WsFirstFlag == "Y"
}

func parseAmt(s string) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.NewFromInt(0)
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	neg := t.Sign() < 0
	absT := t.Abs()
	scaled := absT.Shift(scale)
	s := scaled.StringFixed(0)
	// StringFixed(0) should be plain integer digits (positive)
	// strip any sign or decimal point just in case
	// keep only digits
	var digits strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			digits.WriteByte(s[i])
		}
	}
	ds := digits.String()
	if ds == "" {
		ds = "0"
	}
	totalKeep := intDigits + int(scale)
	if len(ds) > totalKeep {
		ds = ds[len(ds)-totalKeep:]
	}
	var n int64
	for i := 0; i < len(ds); i++ {
		n = n*10 + int64(ds[i]-'0')
	}
	d := decimal.New(n, -scale)
	if neg && n != 0 {
		d = d.Neg()
	}
	return d
}

func formatEdited(val decimal.Decimal, pic string) string {
	neg := val.Sign() < 0
	absVal := val.Abs()
	hasSign := false
	body := pic
	signLen := 0
	if len(pic) > 0 && (pic[0] == '-' || pic[0] == '+') {
		hasSign = true
		body = pic[1:]
		signLen = 1
	}
	intPat := body
	decPat := ""
	if idx := strings.Index(body, "."); idx >= 0 {
		intPat = body[:idx]
		decPat = body[idx+1:]
	}
	intDigits := 0
	for i := 0; i < len(intPat); i++ {
		if intPat[i] == 'Z' || intPat[i] == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for i := 0; i < len(decPat); i++ {
		if decPat[i] == 'Z' || decPat[i] == '9' {
			decDigits++
		}
	}
	truncAbs := absVal.Truncate(int32(decDigits))
	scaled := truncAbs.Shift(int32(decDigits))
	s := scaled.StringFixed(0)
	var digits strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			digits.WriteByte(s[i])
		}
	}
	ds := digits.String()
	if ds == "" {
		ds = "0"
	}
	totalKeep := intDigits + decDigits
	if len(ds) > totalKeep {
		ds = ds[len(ds)-totalKeep:]
	}
	// left pad to totalKeep
	if len(ds) < totalKeep {
		ds = strings.Repeat("0", totalKeep-len(ds)) + ds
	}
	intStr := ""
	fracStr := ""
	if decDigits > 0 {
		if totalKeep > 0 {
			intStr = ds[:intDigits]
			fracStr = ds[intDigits:]
		}
	} else {
		intStr = ds
		fracStr = ""
	}
	// build output
	out := make([]byte, len(pic))
	if hasSign {
		if pic[0] == '-' {
			if neg {
				out[0] = '-'
			} else {
				out[0] = ' '
			}
		} else {
			if neg {
				out[0] = '-'
			} else {
				out[0] = '+'
			}
		}
	}
	suppressed := true
	di := 0
	for k := 0; k < len(intPat); k++ {
		pos := signLen + k
		ch := intPat[k]
		switch ch {
		case ',':
			if suppressed {
				out[pos] = ' '
			} else {
				out[pos] = ','
			}
		case 'Z':
			d := byte('0')
			if di < len(intStr) {
				d = intStr[di]
			}
			di++
			if suppressed && d == '0' {
				out[pos] = ' '
			} else {
				out[pos] = d
				suppressed = false
			}
		case '9':
			d := byte('0')
			if di < len(intStr) {
				d = intStr[di]
			}
			di++
			out[pos] = d
			suppressed = false
		default:
			out[pos] = ch
		}
	}
	// decimal point and fraction
	offset := signLen + len(intPat)
	if decPat != "" || strings.Contains(body, ".") {
		// '.' literal
		if offset < len(out) {
			out[offset] = '.'
		}
		offset++
		fi := 0
		for k := 0; k < len(decPat); k++ {
			ch := decPat[k]
			if ch == '9' || ch == 'Z' {
				d := byte('0')
				if fi < len(fracStr) {
					d = fracStr[fi]
				}
				fi++
				out[offset] = d
			} else {
				out[offset] = ch
			}
			offset++
		}
	}
	_ = hasSign
	return string(out)
}

func openLedger() {
	ledgerLines = nil
	ledgerIdx = 0
	f, err := os.Open("input.dat")
	if err != nil {
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		ledgerLines = append(ledgerLines, sc.Text())
	}
}

func MainPara() {
	openLedger()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	if !FirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	FileRec.BrBranch = line[0:2]
	FileRec.BrAcct = line[2:6]
	FileRec.BrType = line[6:7]
	FileRec.BrAmt = parseAmt(line[7:14])
}

func ProcessPara() {
	if FirstRecord() {
		WsPrevBranch = FileRec.BrBranch
		WsPrevAcct = FileRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if FileRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = FileRec.BrBranch
			WsPrevAcct = FileRec.BrAcct
		} else {
			if FileRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = FileRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatEdited(FileRec.BrAmt, "ZZ,ZZ9.99")
	switch FileRec.BrType {
	case "D":
		WsBal = storeDecimal(WsBal.Add(FileRec.BrAmt), 7, 2)
		fmt.Fprint(os.Stdout, FileRec.BrAcct+" D "+WsAmtEd+"\n")
	case "C":
		WsBal = storeDecimal(WsBal.Sub(FileRec.BrAmt), 7, 2)
		fmt.Fprint(os.Stdout, FileRec.BrAcct+" C "+WsAmtEd+"\n")
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Fprint(os.Stdout, FileRec.BrAcct+" ? SKIPPED\n")
	}
}

func AcctBreakPara() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, "  ACCOUNT "+WsPrevAcct+" BALANCE:"+WsBalEd+"\n")
	WsBranchTot = storeDecimal(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, " BRANCH "+WsPrevBranch+" TOTAL:"+WsTotEd+"\n")
	WsGrandTot = storeDecimal(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, "GRAND TOTAL:"+WsTotEd+"\n")
	sk := WsSkipped % 100
	if sk < 0 {
		sk += 100
	}
	s := fmt.Sprintf("%02d", sk)
	fmt.Fprint(os.Stdout, "SKIPPED: "+s+"\n")
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0
	MainPara()
}
